  "verdict": "request_changes",
  "summary": "The formula incorrectly adds 50 to the product before floor division, breaking symmetry and failing to round exact halves away from zero for negative amounts.",
  "findings": [
    {
      "finding_id": "round_neg_defect",
      "file": "candidate.py",
